window.products.push({"id":175342,"name":"Orbit 2 Pack (20 Total Drippers) Drip System 1 GPH Inline Irrigation Dripper - 10 Pack","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51UAG5VRTBL._AC_SL1000_.jpg","description":"The Orbit DripMaster 1 GPH inline dripper is ideal for watering potted plants and plants spaced 10-inch to 20-inch apart. This dripper allows connection of multiple drippers along a single line of 1/4-inch distribution tubing. Cap off the end of the line by attaching a short piece of drip tubing to the last dripper and insert a 1/4-inch plug. Saves water in drought conditions.","images":["https://m.media-amazon.com/images/I/51UAG5VRTBL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Orbit","source_asin":"B079K7F3B5","category_path":"Home & Kitchen"},"sku":"BM-175342","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B079K7F3B5","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B079K7F3B5","price_pending":true,"merchant_ready":false});
